<script setup lang="ts">
// 词表治理 tab：标签生命周期管理（候选/正式/已合并/已归档）。
// 原 ManageProblemEnrichment.vue 的 Tab2 逻辑整体迁移；疑似重复巡检与候选词上下文在第二批补充。
import { computed, onMounted, ref } from "vue";
import { useCurrentInstance } from "@/util";
import { ShowErrorTips, ShowTextTipsError, ShowTextTipsInfo, type GlobalProperties } from "@/util/tips";
import {
  GetEnrichAliasList,
  GetEnrichTagList,
  GetEnrichTagProblems,
  GetEnrichTagSearch,
  GetEnrichTagSimilar,
  PostEnrichAliasAdd,
  PostEnrichAliasDelete,
  PostEnrichTagApprove,
  PostEnrichTagDeprecate,
  PostEnrichTagMerge,
  PostEnrichTagReactivate,
} from "@/apis/problem-enrichment";
import { tagStatusText, tagStatusTheme } from "./enrich-common";
import type { EnrichTag, TagAlias, TagProblemItem, TagSimilarPair } from "@/types/problem-enrichment";
import { TagStatus } from "@/types/problem-enrichment";
import { useBreakpoint } from "@/composables/useBreakpoint";
import { handleGotoProblem } from "@/util/router";

const globalProperties = useCurrentInstance().globalProperties as GlobalProperties;
const { isMobile } = useBreakpoint();

const pageSize = isMobile.value ? 20 : 50;

const tagList = ref<EnrichTag[]>([]);
const tagTotal = ref(0);
const tagPage = ref(1);
const tagFilter = ref<number[]>([0, 1, 3]);
const tagLoading = ref(false);
const tagMap = ref<Map<number, EnrichTag>>(new Map());

// 合并对话框（目标远程搜索，不限于当前页）
const mergeDialogVisible = ref(false);
const mergeSource = ref<EnrichTag | null>(null);
const mergeTargetId = ref<number | undefined>(undefined);
const mergeTargetOptions = ref<{ label: string; value: number }[]>([]);
const mergeSearching = ref(false);
const mergeSubmitting = ref(false);

// 别名对话框
const aliasDialogVisible = ref(false);
const aliasTag = ref<EnrichTag | null>(null);
const aliasList = ref<TagAlias[]>([]);
const aliasLoading = ref(false);
const aliasInput = ref("");
const aliasSubmitting = ref(false);

// 疑似重复巡检
const similarPairs = ref<TagSimilarPair[]>([]);
const similarLoading = ref(false);

// 候选词使用题目对话框
const tagProblemsVisible = ref(false);
const tagProblemsTag = ref<EnrichTag | null>(null);
const tagProblemsList = ref<TagProblemItem[]>([]);
const tagProblemsLoading = ref(false);

const tagPagination = computed(() => ({
  current: tagPage.value,
  pageSize,
  total: tagTotal.value,
  defaultCurrent: 1,
  defaultPageSize: pageSize,
}));

const tagColumns = [
  { colKey: "name", title: "标签", minWidth: 160 },
  { colKey: "status", title: "状态", width: 150 },
  { colKey: "usage_count", title: "命中题数", width: 100 },
  { colKey: "operation", title: "操作", width: 280, fixed: "right" as const },
];

const fetchTagList = async () => {
  tagLoading.value = true;
  try {
    const res = await GetEnrichTagList(tagFilter.value.length > 0 ? tagFilter.value : null, tagPage.value, pageSize);
    if (res.code === 0) {
      const tagListData = res.data?.list ?? [];
      tagList.value = tagListData;
      tagTotal.value = res.data?.total ?? 0;
      const m = new Map<number, EnrichTag>();
      tagListData.forEach((t) => m.set(t.id, t));
      tagMap.value = m;
    } else {
      ShowErrorTips(globalProperties, res.code);
    }
  } catch (err) {
    console.error(err);
    ShowTextTipsError(globalProperties, "加载标签列表失败");
  } finally {
    tagLoading.value = false;
  }
};

const onTagPageChange = (info: { current: number }) => {
  tagPage.value = info.current;
  fetchTagList();
};

const onTagFilterChange = () => {
  tagPage.value = 1;
  fetchTagList();
};

const handleApproveTag = async (tag: EnrichTag) => {
  const res = await PostEnrichTagApprove(tag.id);
  if (res.code === 0) {
    ShowTextTipsInfo(globalProperties, "已批准为正式标签");
    fetchTagList();
  } else {
    ShowErrorTips(globalProperties, res.code);
  }
};

const handleDeprecateTag = async (tag: EnrichTag) => {
  const res = await PostEnrichTagDeprecate(tag.id);
  if (res.code === 0) {
    ShowTextTipsInfo(globalProperties, "已归档");
    fetchTagList();
  } else {
    ShowErrorTips(globalProperties, res.code);
  }
};

const handleReactivateTag = async (tag: EnrichTag) => {
  const res = await PostEnrichTagReactivate(tag.id);
  if (res.code === 0) {
    ShowTextTipsInfo(globalProperties, "已恢复为正式标签");
    fetchTagList();
  } else {
    ShowErrorTips(globalProperties, res.code);
  }
};

// 合并目标远程搜索
const searchMergeTarget = async (keyword: string) => {
  mergeSearching.value = true;
  try {
    const res = await GetEnrichTagSearch(keyword, 20, [TagStatus.Active]);
    if (res.code === 0) {
      mergeTargetOptions.value = (res.data?.list ?? [])
        .filter((t) => t.id !== mergeSource.value?.id)
        .map((t) => ({ label: `${t.name}（命中 ${t.usage_count}）`, value: t.id }));
    } else {
      ShowErrorTips(globalProperties, res.code);
    }
  } catch (err) {
    console.error(err);
  } finally {
    mergeSearching.value = false;
  }
};

const openMergeDialog = (tag: EnrichTag) => {
  mergeSource.value = tag;
  mergeTargetId.value = undefined;
  mergeTargetOptions.value = [];
  mergeDialogVisible.value = true;
  searchMergeTarget("");
};

const handleMergeSubmit = async () => {
  if (!mergeSource.value || !mergeTargetId.value) {
    return;
  }
  mergeSubmitting.value = true;
  try {
    const res = await PostEnrichTagMerge(mergeSource.value.id, mergeTargetId.value);
    if (res.code === 0) {
      ShowTextTipsInfo(globalProperties, "合并完成，历史关联已保留");
      mergeDialogVisible.value = false;
      fetchTagList();
    } else {
      ShowErrorTips(globalProperties, res.code);
    }
  } catch (err) {
    console.error(err);
    ShowTextTipsError(globalProperties, "操作失败");
  } finally {
    mergeSubmitting.value = false;
  }
};

const mergedTargetName = (row: EnrichTag) => {
  if (row.merged_to_id == null) {
    return "";
  }
  return tagMap.value.get(row.merged_to_id)?.name ?? `#${row.merged_to_id}`;
};

const openAliasDialog = async (tag: EnrichTag) => {
  aliasTag.value = tag;
  aliasInput.value = "";
  aliasDialogVisible.value = true;
  aliasLoading.value = true;
  try {
    const res = await GetEnrichAliasList(tag.id);
    if (res.code === 0) {
      aliasList.value = res.data ?? [];
    } else {
      ShowErrorTips(globalProperties, res.code);
    }
  } catch (err) {
    console.error(err);
    ShowTextTipsError(globalProperties, "操作失败");
  } finally {
    aliasLoading.value = false;
  }
};

const refreshAliasList = async () => {
  if (!aliasTag.value) {
    return;
  }
  const refresh = await GetEnrichAliasList(aliasTag.value.id);
  if (refresh.code === 0) {
    aliasList.value = refresh.data ?? [];
  }
};

const handleAliasAdd = async () => {
  if (!aliasTag.value || !aliasInput.value.trim()) {
    return;
  }
  aliasSubmitting.value = true;
  try {
    const res = await PostEnrichAliasAdd(aliasTag.value.id, aliasInput.value.trim());
    if (res.code === 0) {
      ShowTextTipsInfo(globalProperties, "别名已登记");
      aliasInput.value = "";
      await refreshAliasList();
    } else {
      ShowErrorTips(globalProperties, res.code);
    }
  } catch (err) {
    console.error(err);
    ShowTextTipsError(globalProperties, "操作失败");
  } finally {
    aliasSubmitting.value = false;
  }
};

const handleAliasDelete = async (id: number) => {
  const res = await PostEnrichAliasDelete(id);
  if (res.code === 0) {
    ShowTextTipsInfo(globalProperties, "别名已删除");
    await refreshAliasList();
  } else {
    ShowErrorTips(globalProperties, res.code);
  }
};

// ── 疑似重复巡检 ──
const fetchSimilar = async () => {
  similarLoading.value = true;
  try {
    const res = await GetEnrichTagSimilar();
    if (res.code === 0) {
      similarPairs.value = res.data?.list ?? [];
    } else {
      ShowErrorTips(globalProperties, res.code);
    }
  } catch (err) {
    console.error(err);
  } finally {
    similarLoading.value = false;
  }
};

// 从疑似重复对打开合并对话框（左词并入右词，可自行调整方向）
const openMergeFromSimilar = (pair: TagSimilarPair) => {
  const from = { id: pair.left_id, name: pair.left_name } as EnrichTag;
  mergeSource.value = from;
  mergeTargetId.value = pair.right_id;
  mergeTargetOptions.value = [{ label: `${pair.right_name}（命中 ${pair.right_usage}）`, value: pair.right_id }];
  mergeDialogVisible.value = true;
};

// ── 候选词使用题目 ──
const openTagProblems = async (tag: EnrichTag) => {
  tagProblemsTag.value = tag;
  tagProblemsList.value = [];
  tagProblemsVisible.value = true;
  tagProblemsLoading.value = true;
  try {
    const res = await GetEnrichTagProblems(tag.id);
    if (res.code === 0) {
      tagProblemsList.value = res.data?.list ?? [];
    } else {
      ShowErrorTips(globalProperties, res.code);
    }
  } catch (err) {
    console.error(err);
    ShowTextTipsError(globalProperties, "加载使用题目失败");
  } finally {
    tagProblemsLoading.value = false;
  }
};

const gotoProblem = (key: string) => {
  if (key) {
    handleGotoProblem(key);
  }
};

onMounted(() => {
  fetchTagList();
  fetchSimilar();
});
</script>

<template>
  <div class="enrich-tag">
    <!-- 疑似重复巡检：归一化名相似（编辑距离/公共前缀），建议合并 -->
    <t-loading :loading="similarLoading" size="small">
      <div v-if="similarPairs.length" class="similar-block">
        <div class="similar-title">
          疑似重复（归一化名相似，建议合并）
          <t-button size="small" variant="text" @click="fetchSimilar">刷新巡检</t-button>
        </div>
        <div v-for="p in similarPairs" :key="`${p.left_id}-${p.right_id}`" class="similar-row">
          <span class="similar-pair">
            <b>{{ p.left_name }}</b>（{{ p.left_usage }} 题） ↔ <b>{{ p.right_name }}</b>（{{ p.right_usage }}
            题）
          </span>
          <t-tag size="small" :theme="p.similarity >= 0.85 ? 'danger' : 'warning'" variant="light">
            相似 {{ Math.round(p.similarity * 100) }}%
          </t-tag>
          <t-button size="small" variant="text" theme="primary" @click="openMergeFromSimilar(p)">
            合并处理
          </t-button>
        </div>
      </div>
    </t-loading>

    <div class="enrich-toolbar">
      <t-select
        v-model="tagFilter"
        :options="[
          { label: '候选', value: 0 },
          { label: '正式', value: 1 },
          { label: '已合并', value: 2 },
          { label: '已归档', value: 3 },
        ]"
        multiple
        clearable
        placeholder="按状态筛选"
        style="min-width: 220px"
        @change="onTagFilterChange"
      />
      <t-button variant="outline" @click="fetchTagList">刷新</t-button>
    </div>

    <div class="enrich-table-wrap">
      <t-table
        :data="tagList"
        :columns="tagColumns"
        :loading="tagLoading"
        row-key="id"
        table-layout="auto"
        :pagination="tagPagination"
        @page-change="onTagPageChange"
      >
        <template #name="{ row }">
          <span>{{ row.name }}</span>
          <t-tag v-if="row.source === 'ai'" size="small" theme="primary" variant="outline" class="enrich-ai-tag">
            AI
          </t-tag>
        </template>
        <template #status="{ row }">
          <t-tag :theme="tagStatusTheme[row.status]" variant="light">{{ tagStatusText[row.status] }}</t-tag>
          <span v-if="row.status === 2 && row.merged_to_id" class="enrich-merge-target">
            → {{ mergedTargetName(row) }}
          </span>
        </template>
        <template #usage_count="{ row }">{{ row.usage_count }}</template>
        <template #operation="{ row }">
          <t-space size="small" break-line>
            <t-button
              v-if="row.status === 0 || row.status === 1"
              size="small"
              variant="text"
              @click="openTagProblems(row)"
            >
              题目
            </t-button>
            <t-button
              v-if="row.status === 0"
              size="small"
              variant="text"
              theme="success"
              @click="handleApproveTag(row)"
            >
              批准
            </t-button>
            <t-button
              v-if="row.status !== 2"
              size="small"
              variant="text"
              theme="primary"
              @click="openMergeDialog(row)"
            >
              合并
            </t-button>
            <t-button
              v-if="row.status === 3"
              size="small"
              variant="text"
              theme="success"
              @click="handleReactivateTag(row)"
            >
              恢复
            </t-button>
            <t-popconfirm
              v-if="row.status !== 2 && row.status !== 3"
              content="归档后该标签不再用于新词匹配，历史关联保留，确定归档？"
              @confirm="handleDeprecateTag(row)"
            >
              <t-button size="small" variant="text" theme="danger">归档</t-button>
            </t-popconfirm>
            <t-button size="small" variant="text" @click="openAliasDialog(row)">别名</t-button>
          </t-space>
        </template>
      </t-table>
    </div>

    <!-- 合并对话框（目标远程搜索） -->
    <t-dialog
      v-model:visible="mergeDialogVisible"
      header="合并标签"
      :confirm-on-enter="false"
      :confirm-loading="mergeSubmitting"
      @confirm="handleMergeSubmit"
    >
      <p v-if="mergeSource">
        将标签「<b>{{ mergeSource.name }}</b>」的全部题目关联与别名并入目标标签；源标签置为「已合并」并保留指向，历史关联不丢失。
      </p>
      <t-select
        v-model="mergeTargetId"
        :options="mergeTargetOptions"
        :loading="mergeSearching"
        :filterable="true"
        clearable
        placeholder="输入标签名搜索合并目标（正式标签）"
        @search="searchMergeTarget"
      />
    </t-dialog>

    <!-- 别名对话框 -->
    <t-dialog v-model:visible="aliasDialogVisible" header="标签别名管理" :footer="false" width="560px">
      <p v-if="aliasTag">标签「<b>{{ aliasTag.name }}</b>」的归一别名（AI/人工输出这些词时直接映射到该标签）：</p>
      <t-loading :loading="aliasLoading">
        <div v-if="aliasList.length === 0" class="enrich-empty">暂无别名</div>
        <div v-for="a in aliasList" :key="a.id" class="alias-row">
          <span>{{ a.alias }}</span>
          <t-button size="small" variant="text" theme="danger" @click="handleAliasDelete(a.id)">删除</t-button>
        </div>
      </t-loading>
      <t-input v-model="aliasInput" placeholder="新增别名（自动做全半角/大小写归一）" class="alias-input" @enter="handleAliasAdd" />
      <t-button theme="primary" :loading="aliasSubmitting" style="margin-top: 8px" @click="handleAliasAdd">
        添加别名
      </t-button>
    </t-dialog>

    <!-- 标签使用题目对话框（候选词审查上下文） -->
    <t-dialog
      v-model:visible="tagProblemsVisible"
      :header="`标签「${tagProblemsTag?.name ?? ''}」挂载的题目`"
      :footer="false"
      width="560px"
    >
      <t-loading :loading="tagProblemsLoading">
        <div v-if="!tagProblemsList.length" class="enrich-empty">暂无题目使用该标签</div>
        <div v-for="p in tagProblemsList" :key="p.id" class="tag-problem-row">
          <t-button variant="text" @click="gotoProblem(p.key)">
            {{ p.key }} {{ p.title }}
          </t-button>
        </div>
        <div v-if="tagProblemsList.length" class="tag-problem-hint">（最多显示最近 20 道，共 {{ tagProblemsTag?.usage_count ?? 0 }} 题）</div>
      </t-loading>
    </t-dialog>
  </div>
</template>

