<script setup lang="ts">
// 题目产出详情抽屉（只读）：题面上下文 + 状态 + 五类最新产出（含内部）+ 版本历史 + 调用账本。
// 任何入口（题目列表「查看产出」/ 审核卡片「全部产出」/ 总览活动与失败面板）都打开它，
// 查看与修改分离——编辑走「人工标注」按钮打开校正抽屉。
import { nextTick, ref, watch } from "vue";
import { useCurrentInstance } from "@/util";
import { ShowErrorTips, ShowTextTipsError, ShowTextTipsInfo, type GlobalProperties } from "@/util/tips";
import { GetEnrichDetail, PostEnrichSuggestionStatus } from "@/apis/problem-enrichment";
import echarts, { type EChartsOption } from "@/util/echarts";
import {
  callStatusText,
  callStatusTheme,
  fmtSec,
  fmtTime,
  reviewStatusText,
  reviewStatusTheme,
  stateStatusText,
  stateStatusTheme,
  stageText,
  taskTypeText,
  visibilityText,
} from "./enrich-common";
import EnrichPipelineSteps from "./EnrichPipelineSteps.vue";
import AnnotationCard from "./AnnotationCard.vue";
import type { EnrichProblemDetail } from "@/types/problem-enrichment";
import { useBreakpoint } from "@/composables/useBreakpoint";
import { handleGotoProblem } from "@/util/router";

const props = defineProps<{
  visible: boolean;
  problemId: number;
  dataVersion: number; // 外部动作（重判/人工定稿）后递增，抽屉可见时自动刷新
}>();

const emit = defineEmits<{
  (e: "update:visible", v: boolean): void;
  (e: "open-curator", problemId: number, taskType: string): void;
  (e: "requeue", problemId: number): void; // 交给父组件执行重判并刷新
}>();

const globalProperties = useCurrentInstance().globalProperties as GlobalProperties;
const { isMobile } = useBreakpoint();

const loading = ref(false);
const detail = ref<EnrichProblemDetail | null>(null);
const statementOpen = ref(false);
const callsOpen = ref(false);
const radarRef = ref<HTMLElement | null>(null);
let radarChart: ReturnType<typeof echarts.init> | null = null;

const close = () => emit("update:visible", false);

const difficultyAnn = () => detail.value?.annotations.find((a) => a.task_type === "difficulty");

const load = async () => {
  if (!props.problemId) {
    return;
  }
  loading.value = true;
  try {
    const res = await GetEnrichDetail(props.problemId);
    if (res.code === 0) {
      detail.value = res.data;
      statementOpen.value = false;
      callsOpen.value = false;
      await nextTick();
      renderRadar();
    } else {
      ShowErrorTips(globalProperties, res.code);
    }
  } catch (err) {
    console.error(err);
    ShowTextTipsError(globalProperties, "加载题目产出详情失败");
  } finally {
    loading.value = false;
  }
};

// 难度雷达图（四维，1~5）；移动端隐藏不渲染
const renderRadar = () => {
  if (isMobile.value) {
    return;
  }
  const ann = difficultyAnn();
  const dom = radarRef.value;
  if (!dom || !ann) {
    return;
  }
  if (radarChart) {
    radarChart.dispose();
    radarChart = null;
  }
  const p = ann.payload as any;
  radarChart = echarts.init(dom, null, { renderer: "canvas" });
  const option: EChartsOption = {
    radar: {
      indicator: [
        { name: "思维", max: 5 },
        { name: "算法", max: 5 },
        { name: "实现", max: 5 },
        { name: "陷阱", max: 5 },
      ],
      radius: "65%",
      splitNumber: 5,
      axisName: { color: "var(--td-text-color-secondary)" },
    },
    series: [
      {
        type: "radar",
        data: [
          {
            value: [p.thinking ?? 0, p.algorithm ?? 0, p.implementation ?? 0, p.pitfalls ?? 0],
            areaStyle: { opacity: 0.25 },
          },
        ],
      },
    ],
  };
  radarChart.setOption(option);
};

watch(
  () => [props.visible, props.problemId],
  () => {
    if (props.visible && props.problemId) {
      load();
    } else if (radarChart) {
      radarChart.dispose();
      radarChart = null;
    }
  }
);

// 重判/人工定稿后抽屉仍打开时自动刷新详情
watch(
  () => props.dataVersion,
  () => {
    if (props.visible && props.problemId) {
      load();
    }
  }
);

// 重判：交给父组件执行（会刷新各视图），本抽屉不关闭以便观察进度
const handleRejudge = () => {
  if (!detail.value?.state) {
    return;
  }
  emit("requeue", props.problemId);
};

// 建议条目状态展示（t-select 选项的 label 即状态文案）
const suggestionStatusOptions = [
  { label: "待处理", value: "open" },
  { label: "已采纳", value: "done" },
  { label: "已忽略", value: "ignored" },
];

// 出题人标记建议状态（采纳率即评估数据）
const suggestionStatusSaving = ref(false);
const setSuggestionStatus = async (itemIndex: number, status: string) => {
  suggestionStatusSaving.value = true;
  try {
    const res = await PostEnrichSuggestionStatus(
      props.problemId,
      itemIndex,
      status as "open" | "done" | "ignored"
    );
    if (res.code === 0) {
      ShowTextTipsInfo(globalProperties, "建议状态已更新");
      await load();
    } else {
      ShowErrorTips(globalProperties, res.code);
    }
  } catch (err) {
    console.error(err);
    ShowTextTipsError(globalProperties, "操作失败");
  } finally {
    suggestionStatusSaving.value = false;
  }
};

const gotoProblem = () => {
  if (detail.value?.problem?.key) {
    handleGotoProblem(detail.value.problem.key);
  }
};
</script>

<template>
  <t-drawer
    :visible="visible"
    :header="`题目产出详情 · ${detail?.problem?.key || `#${problemId}`} ${detail?.problem?.title ?? ''}`"
    size="860px"
    :footer="false"
    :close-on-overlay-click="false"
    @close="close"
  >
    <t-loading :loading="loading">
      <template v-if="detail">
        <!-- 状态与操作 -->
        <div class="detail-head">
          <t-space size="small" break-line>
            <t-tag
              v-if="detail.state"
              :theme="stateStatusTheme[detail.state.status]"
              variant="light"
            >
              {{ stateStatusText[detail.state.status] }}
            </t-tag>
            <EnrichPipelineSteps :steps="detail.steps ?? []" size="md" />
            <span v-if="detail.state" class="detail-meta">
              尝试 {{ detail.state.attempt }} · 更新 {{ fmtTime(detail.state.modify_time) }}
            </span>
          </t-space>
          <t-space size="small">
            <t-button variant="outline" size="small" @click="gotoProblem">去题目页</t-button>
            <t-popconfirm
              content="强制重新入队并重新跑完整流水线（人工已定稿的类型会保留），确定？"
              @confirm="handleRejudge"
            >
              <t-button size="small" theme="primary" variant="outline">重判</t-button>
            </t-popconfirm>
            <t-button
              size="small"
              theme="success"
              variant="outline"
              @click="emit('open-curator', problemId, 'summary')"
            >
              人工标注
            </t-button>
          </t-space>
        </div>
        <t-alert
          v-if="detail.state?.message"
          theme="danger"
          class="detail-alert"
          :message="detail.state.message"
        />

        <!-- 题面（折叠） -->
        <div class="detail-section">
          <div class="detail-section-head">
            <t-button
              size="small"
              variant="text"
              theme="primary"
              @click="statementOpen = !statementOpen"
            >
              {{ statementOpen ? "收起题面" : "展开题面" }}
            </t-button>
            <span class="detail-meta">
              时限 {{ detail.problem.time_limit }}ms · 内存 {{ detail.problem.memory_limit }}KB ·
              {{ detail.problem.judge_type === 1 ? "SPJ 特殊判题" : "普通比较判题" }}
            </span>
          </div>
          <div v-if="statementOpen" class="detail-statement">{{ detail.problem.description }}</div>
          <div v-if="(detail.problem.tag_names ?? []).length" class="detail-tags">
            <t-tag v-for="n in detail.problem.tag_names ?? []" :key="n" size="small" variant="outline">{{ n }}</t-tag>
          </div>
        </div>

        <!-- 五类产出 -->
        <div
          v-for="a in detail.annotations ?? []"
          :key="a.task_type"
          class="detail-card"
          :class="{ 'detail-card-rejected': a.review_status === 'rejected' }"
        >
          <div class="detail-card-head">
            <span class="detail-card-title">
              {{ taskTypeText[a.task_type] || a.task_type }}
            </span>
            <t-space size="small">
              <t-tag variant="outline" size="small">{{ visibilityText[a.visibility] || a.visibility }}</t-tag>
              <t-tag v-if="a.source === 'human'" theme="default" variant="dark" size="small">人工定稿</t-tag>
              <t-tag
                v-if="a.review_status"
                :theme="reviewStatusTheme[a.review_status]"
                variant="light"
                size="small"
              >
                {{ reviewStatusText[a.review_status] }}
              </t-tag>
              <span class="detail-meta">置信 {{ Math.round(a.confidence * 100) }}%</span>
              <span class="detail-meta">{{ fmtTime(a.insert_time) }}</span>
              <t-button
                size="small"
                variant="text"
                theme="success"
                @click="emit('open-curator', problemId, a.task_type)"
              >
                编辑
              </t-button>
            </t-space>
          </div>

          <div class="detail-card-body">
            <AnnotationCard
              :task-type="a.task_type"
              :payload="a.payload ?? {}"
              :show-evidence="true"
            />
            <!-- 难度雷达图（移动端隐藏） -->
            <div
              v-if="a.task_type === 'difficulty' && !isMobile"
              ref="radarRef"
              class="detail-radar"
            />
          </div>

          <!-- 建议条目状态（出题人可标记：采纳率即评估数据） -->
          <div
            v-if="a.task_type === 'suggestion' && ((a.payload as any)?.items ?? []).length"
            class="detail-sugg-status"
          >
            <div v-for="(s, i) in (a.payload as any).items" :key="i" class="detail-sugg-row">
              <span class="detail-sugg-text">#{{ i + 1 }} {{ s.suggestion }}</span>
              <t-select
                :model-value="s.status || 'open'"
                :options="suggestionStatusOptions"
                size="small"
                style="width: 96px"
                :disabled="suggestionStatusSaving"
                @change="(v: string) => setSuggestionStatus(i, v)"
              />
            </div>
          </div>

          <!-- 版本历史 -->
          <div v-if="(a.history ?? []).length" class="detail-history">
            <t-collapse :default-value="[]">
              <t-collapse-panel :value="`history-${a.task_type}`" :header="`历史版本（${(a.history ?? []).length} 版，旧→新）`">
                <div v-for="h in a.history ?? []" :key="h.id" class="detail-history-row">
                  <t-space size="small">
                    <span class="detail-meta">{{ fmtTime(h.insert_time) }}</span>
                    <t-tag v-if="h.source === 'human'" theme="default" variant="dark" size="small">人工</t-tag>
                    <t-tag v-else variant="light" size="small">AI</t-tag>
                    <t-tag v-if="h.golden" theme="warning" variant="dark" size="small">黄金集</t-tag>
                    <t-tag v-if="h.review_status === 'rejected'" theme="danger" variant="light" size="small">
                      已驳回
                    </t-tag>
                    <span class="detail-meta">置信 {{ Math.round(h.confidence * 100) }}%</span>
                  </t-space>
                  <div class="detail-history-payload">
                    <AnnotationCard :task-type="a.task_type" :payload="h.payload ?? {}" />
                  </div>
                </div>
              </t-collapse-panel>
            </t-collapse>
          </div>
        </div>

        <div v-if="!detail.annotations.length" class="detail-empty">
          暂无产出标注（该题尚未成功富化或未人工标注）
        </div>

        <!-- 调用账本 -->
        <div class="detail-section">
          <t-button size="small" variant="text" theme="primary" @click="callsOpen = !callsOpen">
            {{ callsOpen ? "收起调用账本" : `展开调用账本（${(detail.calls ?? []).length} 条）` }}
          </t-button>
          <template v-if="callsOpen">
            <div v-if="!(detail.calls ?? []).length" class="detail-empty">暂无调用记录</div>
            <div v-for="c in detail.calls ?? []" :key="c.id" class="call-row">
              <div class="call-row-head">
                <t-space size="small">
                  <t-tag theme="primary" variant="light">{{ stageText[c.stage] || c.stage }}</t-tag>
                  <t-tag :theme="callStatusTheme[c.status] || 'default'" variant="light">
                    {{ callStatusText[c.status] || c.status }}
                  </t-tag>
                  <span class="detail-meta">{{ c.model }} · 第 {{ c.attempt }} 次</span>
                </t-space>
                <span class="detail-meta">{{ fmtTime(c.insert_time) }}</span>
              </div>
              <div class="call-row-meta">
                耗时 {{ fmtSec(c.duration_ms) }} · token {{ c.total_tokens.toLocaleString() }}（提示
                {{ c.prompt_tokens }} / 生成 {{ c.completion_tokens }}）
              </div>
              <div v-if="c.error" class="call-error">{{ c.error }}</div>
            </div>
          </template>
        </div>
      </template>
      <div v-else-if="!loading" class="detail-empty">未加载到产出详情</div>
    </t-loading>
  </t-drawer>
</template>

